(window.webpackJsonp=window.webpackJsonp||[]).push([[163],{492:function(e,t,r){"use strict";r.r(t);var i=r(7),a=function(e){e.options.__data__block__={mermaid_382ee1c8:'graph TB\n    P["Pajitnov 的代码<br/>苏联科学院，1984<br/>法律上归国家所有"] --\x3e S["Robert Stein / Andromeda<br/>合同没签，先开卖"]\n    S --\x3e M["Mirrorsoft<br/>Robert Maxwell 的传媒帝国"]\n    S --\x3e SH["Spectrum HoloByte<br/>美版，1988"]\n    M --\x3e T["Tengen / Atari Games<br/>主机 + 街机"]\n    T --\x3e B["Bullet-Proof Software<br/>Henk Rogers，日本 Famicom"]\n    E["Elorg<br/>苏联对外贸易机构<br/>唯一真正的权利人"]\n    E -.->|"1989.2 主机+掌机<br/>数百万美元"| N["任天堂"]\n    B -.->|"1989 引荐"| N\n'}},o=Object(i.a)({},(function(){var e=this,t=e.$createElement,r=e._self._c||t;return r("ContentSlotsDistributor",{attrs:{"slot-key":e.$parent.slotKey}},[r("p",[e._v("把俄罗斯方块的规则讲清楚，只需要一句话：七种方块从天上落下来，落进一口十格宽、二十格深的井里，横竖填满一行，这一行就消失。")]),e._v(" "),r("p",[e._v("把它的版权讲清楚，需要的不是一句话，是一张图。1989 年春天，西方市场上同时有四家公司都相信自己是 Tetris 的正版，其中两家已经把印着方块的游戏压上了货架互相竞争；而真正有权签发许可证的那家机构，远在莫斯科，它自己也是在那一年才把账理清楚的。")]),e._v(" "),r("p",[e._v("更妙的是这两个故事的落差：游戏本身诞生在一台没有图形能力的计算机上，而它搅动的是三个国家的公司、一个报纸传媒帝国、一个国家的对外贸易机构，和冷战末期一笔没人预料到的外汇。")]),e._v(" "),r("h2",{attrs:{id:"一、1984-年-6-月-6-日-莫斯科"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#一、1984-年-6-月-6-日-莫斯科"}},[e._v("#")]),e._v(" 一、1984 年 6 月 6 日，莫斯科")]),e._v(" "),r("p",[e._v("Alexey Pajitnov 那年在苏联科学院计算中心工作，研究语音识别。他的测试机是一台 Elektronika 60——算力不弱，但没有图形系统，屏幕上所有的「画面」都靠字符拼出来。")]),e._v(" "),r("p",[e._v("Pajitnov 童年玩过一种五格骨牌拼图（pentomino）：十二种形状，任务是把它们填进一个盒子。他把它搬上计算机，发现两个问题：十二种形状太多，玩家来不及认；字符屏幕太窄，也摆不下那么大的阵仗。于是五格砍成四格——四种格子的组合一共七种：I、O、T、S、Z、J、L。游戏的名字 Tetris，是希腊语的「四」（tetra）加上他热爱的网球（tennis）。")]),e._v(" "),r("p",[e._v("1984 年 6 月 6 日，第一版能玩的 Tetris 在这台机器上转了起来。它没有图形，没有声音，下落的方块是一对对方括号。它也从法律上不属于 Pajitnov：用国家的机器、国家的时间做出来的东西，是国家财产。写它的人得到的是荣誉，不是权利。")]),e._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/05/fig-tetris-e60.jpeg",alt:"第一版 Tetris 跑在一台没有图形系统的终端上，方块是字符拼出来的",loading:"lazy"}})]),e._v(" "),r("h2",{attrs:{id:"二、先上货架-后签合同"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#二、先上货架-后签合同"}},[e._v("#")]),e._v(" 二、先上货架，后签合同")]),e._v(" "),r("p",[e._v("Tetris 的传播不靠商店，靠软盘和磁带：莫斯科的计算机圈子先玩上，然后是列宁格勒，然后是整个东欧的计算机研究所。1985 年前后，匈牙利科学院的研究者把它移植到了 Apple II 和 Commodore 64 上——这批移植版，成了它后来一切命运的起点。")]),e._v(" "),r("p",[e._v("1986 年，英国游戏掮客 Robert Stein 在布达佩斯的一个展会上看见了 Apple II 版 Tetris。他给 Pajitnov 发去电传谈授权，得到的回复来自一个无权处置自己作品的人——Pajitnov 客气地绕开了所有关于钱的问题，因为这部作品的商业权利不在他手里，在国家和它指定的外贸机构手里。")]),e._v(" "),r("p",[e._v("那家机构叫 Elorg（Elektronorgtechnica），苏联对西方出口计算机软硬件的唯一窗口。Stein 飞到莫斯科开始谈判，而苏联式的谈判有个特点：慢。每一份合同都要盖不完的章、开不完的会。")]),e._v(" "),r("p",[e._v("Stein 没等。在 Elorg 的合同还在路上的时候，他已经把「电脑版 Tetris」的许可卖给了伦敦的 Mirrorsoft——老板 Robert Maxwell，报纸传媒帝国的掌门人，和苏联高层交情不浅。1986 年 11 月，第一批 Tetris 以商品身份出现在西方货架，版权方一栏印着 Mirrorsoft；一年后，美国又多了一版 Spectrum HoloByte 出版的 Tetris，包装封面是一幅苏维埃现实主义风格的油画。")]),e._v(" "),r("p",[e._v("这两家公司卖的，严格说都是「无授权版」——Stein 自己当时也还没拿到授权。而离这场狂欢最远的那个男人、游戏真正的作者，一分钱都没有拿到。")]),e._v(" "),r("h2",{attrs:{id:"三、击鼓传花"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#三、击鼓传花"}},[e._v("#")]),e._v(" 三、击鼓传花")]),e._v(" "),r("p",[e._v("1988 年，慢了两年多的 Elorg 终于和 Stein 签下正式合同。这份合同授予的是「个人计算机」上的 Tetris 权利——签合同时没人多想这几个字，但它们很快会成为整场战争的胜负手。")]),e._v(" "),r("p",[e._v("因为许可链没有停。Stein 拿到的「电脑版」许可被继续往下拆着卖：主机和街机的一支落到了 Atari Games 的家用机品牌 Tengen 手里；同一条链再往东延伸一段，日本市场的 Famicom 版落到了 Henk Rogers 的 Bullet-Proof Software 手里。Rogers 是个在日美之间来回创业的人，他出版的 Famicom 版 Tetris 在 1988 年 12 月上市，卖了约 200 万份。")]),e._v(" "),r("p",[e._v("到这里，局面是：莫斯科以外的每一家都相信自己在卖正版，而他们手里的「权利」，全部来自一份只覆盖个人计算机的合同，外加几层没经过莫斯科确认的转许可。Maxwell 的帝国以为买到了一座矿，Atari 以为锁定了主机市场——只有莫斯科知道，这些矿和锁，其实谁都没拿到。")]),e._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/05/fig-tetris-chain.jpeg",alt:"一张被反复转卖的许可链：每一次转手，离莫斯科都更远一点",loading:"lazy"}})]),e._v(" "),r("Mermaid",{attrs:{id:"mermaid_382ee1c8",graph:e.$dataBlock.mermaid_382ee1c8}}),r("h2",{attrs:{id:"四、1989-年-2-月-一个拿着旅游签证的日本人"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#四、1989-年-2-月-一个拿着旅游签证的日本人"}},[e._v("#")]),e._v(" 四、1989 年 2 月，一个拿着旅游签证的日本人")]),e._v(" "),r("p",[e._v("Nintendo of America 想要 Tetris：主机版想要，掌机版更想要——GameBoy 就快上市了，他们缺一个能让所有人随时掏出机器的游戏。但美版 NES 的权利看起来已经在 Tengen 手里，这时候主动揽下这件事的，是做 Famicom 版的 Henk Rogers 本人：他比谁都清楚，如果任天堂拿不到莫斯科正主的授权，他自己的生意和任天堂的掌机都会悬在半空。")]),e._v(" "),r("p",[e._v("Rogers 拿着旅游签证只身飞进莫斯科，没有邀请函，没有预约，打了个车直奔 Elorg 的办公室。")]),e._v(" "),r("p",[e._v("接待他的是 Elorg 的谈判负责人 Nikolai Belikov。过去两年，Belikov 一直在看西方这边表演：Stein 拖着版税不结，Atari 高调宣布了主机版，Mirrorsoft 自称握有街机和主机权利——而所有这一切的合同依据，只有那份写着「个人计算机」的协议。Belikov 早就把账算明白了：莫斯科以外的所有人，都在转卖莫斯科没有给出去的东西。")]),e._v(" "),r("p",[e._v("Rogers 坐下来做的第一件事是交底：他如实交代了自己 Famicom 版许可的来龙去脉——它同样出自那条糊里糊涂的链，他愿意把文件摊开给 Elorg 看。事后流传的版本里，Belikov 对他说了一句：你是唯一一个跟我说真话的人。")]),e._v(" "),r("p",[e._v("后面的事就顺了。Rogers 把任天堂的谈判团队引进莫斯科——Nintendo of America 总裁 Minoru Arakawa 和法务负责人 Howard Lincoln 随后到齐。Elorg 把主机和掌机的权利单独签给了任天堂，价格是数百万美元；同一场谈判里，Belikov 顺手让 Stein 在补充协议上签了字，把他手里的许可明确改成了「不含主机」。Stein 签得很快——不签，他连电脑版都可能保不住。")]),e._v(" "),r("p",[e._v("从法律意义上讲，这场战争在莫斯科的这张桌上就打完了。但 1989 年的美国，还要用几个月时间和几十万盒卡带来确认这一点。")]),e._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/05/fig-tetris-moscow.jpeg",alt:"莫斯科的冬天：这场谈判没有签保密协议，双方都记得每一个细节",loading:"lazy"}})]),e._v(" "),r("h2",{attrs:{id:"五、判决、召回-和一条三千五百万份的曲线"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#五、判决、召回-和一条三千五百万份的曲线"}},[e._v("#")]),e._v(" 五、判决、召回，和一条三千五百万份的曲线")]),e._v(" "),r("p",[e._v("Tengen 不服。Atari Games 的算盘很清楚：自己的主机权利走的是 Mirrorsoft 那条链，墨水都干了，凭什么莫斯科一句话就作废？1989 年 5 月，Tengen 版 NES Tetris 照常上市，广告铺开，销售曲线抬头。")]),e._v(" "),r("p",[e._v("任天堂的律师把莫斯科的原件合同拍在了加州北区联邦法院的桌上。1989 年 6 月，法官 Fern Smith 裁定：Tengen 的权利链不成立，Elorg 的合同把主机权利只给了任天堂，初步禁令生效。Tengen 版 Tetris 从商店下架，据事后统计，约 26.8 万盒卡带被召回销毁；Atari 上诉，1992 年维持原判。讽刺的是，这一版因为存世稀少，后来成了收藏市场的圣杯。")]),e._v(" "),r("p",[e._v("同年夏天，GameBoy 在北美上市，Tetris 随机捆绑。NOA 内部原本对它有保留：一款没有主角、没有关卡、画面朴素的抽象游戏，营销部门不确定谁会买。总裁 Arakawa 力排众议，把它塞进了包装盒。这台掌机后来的寿命销量是 1.18 亿台，随它售出的 Tetris 卡带最终累计约 3500 万份——是这款游戏在单个平台上最成功的一笔。任天堂自家的 NES 版也卖了约 800 万份，三十年后，那版黑带机器还养着一场全球复古竞速锦标赛（Classic Tetris World Championship）。")]),e._v(" "),r("p",[e._v("方块下落得太多，还会渗进现实：玩得久了的人合上眼，天花板上的方块还在落。1989 年，英文媒体给这个现象起了名字，Tetris Effect。流传甚广的一段记载是，Pajitnov 的老朋友、心理学家 Vladimir Pokhilko 把自己实验室里所有 Tetris 的拷贝全部收缴销毁，理由是他手下的研究员停不下来——这大概是 Tetris 被人下过的最重的一道封禁令，范围只有一间实验室。")]),e._v(" "),r("p",[r("img",{attrs:{src:"/images/2026/11/05/fig-tetris-gameboy.jpeg",alt:"1989 年：一台口袋里的机器，和随它售出的三千五百万份方块",loading:"lazy"}})]),e._v(" "),r("h2",{attrs:{id:"六、尾声"}},[r("a",{staticClass:"header-anchor",attrs:{href:"#六、尾声"}},[e._v("#")]),e._v(" 六、尾声")]),e._v(" "),r("p",[e._v("1991 年 11 月 5 日——整整 35 年前的今天——Robert Maxwell 从他自己的游艇 Lady Ghislaine 上落海，第二天被发现漂在加那利群岛外的海面上。Mirrorsoft 在这场战争里最后连一张有效的许可证都没剩下。")]),e._v(" "),r("p",[e._v("Stein 的 Andromeda 在电脑版上又收了几年版税，然后从故事里淡出。Pajitnov 也在 1991 年离开苏联去了美国，1996 年加入微软，后来做出了 Hexic。同一年，继承了 Elorg 权利的俄方把 Tetris 还给了它的作者——距离他写下这个游戏，已经过去 12 年，而他此前没有拿到过一分版税。Pajitnov 和 Henk Rogers 成立了 The Tetris Company，把散落各处的授权收拢进一家公司：从此，任何想用这七种方块做游戏的人，都得先过他们这一关。")]),e._v(" "),r("p",[e._v("Pajitnov 后来在采访里被反复问到那十二年：所有的钱都归了国家，后悔吗？他的回答大意是：我没有为了钱去设计 Tetris，钱去了哪里并不重要；重要的是，它最后回到了我的名字下面。")]),e._v(" "),r("p",[e._v("截至 2024 年，Tetris 全平台累计销量超过 5 亿份，多份榜单把它列为史上最畅销的游戏。而回看整个故事：一个几乎没有对外卖出过任何软件的国家，把它最成功的一件软件出口做成了一口十格宽、二十格深的井——律师函、谈判、判决、召回，层层叠叠一整场战争，最后分出胜负的，是一件最简单的事：谁先说了实话。")])],1)}),[],!1,null,null,null);"function"==typeof a&&a(o);t.default=o.exports}}]);